(()=>{const key='popomo-print-orders',deliveryShippingCents=400;function shipping(order){return ['paid','printed'].includes(order.status)?Math.max(0,Math.round(Number(order.shippingCents)||0)):order.fulfillment?.method==='delivery'?deliveryShippingCents:0;}function normalize(o){const fulfillment=o.fulfillmentSnapshot||o.fulfillment||{};return {...o,fulfillment,shippingCents:shipping({...o,fulfillment}),quantity:Math.max(1,Math.min(20,Number(o.quantity)||1)),aiCostCents:Number(o.aiCostCents)||0,aiUsed:o.aiUsed??o.source==='ai',paymentMethod:o.paymentMethod||(['paid','printed'].includes(o.status)?'online':null)};}function list(){try{const data=JSON.parse(sessionStorage.getItem(key)||'[]');return Array.isArray(data)?data.map(normalize).sort((a,b)=>b.createdAt-a.createdAt):[];}catch{return [];}}function get(id){return list().find(o=>o.id===id);}function update(order){const previous=get(order.id);if(previous&&['paid','printed'].includes(previous.status)){const snapshot=previous.fulfillmentSnapshot||previous.fulfillment||{};order={...order,fulfillment:snapshot,fulfillmentSnapshot:snapshot,shippingCents:previous.shippingCents};}else if(['paid','printed'].includes(order.status)){const snapshot=order.fulfillmentSnapshot||order.fulfillment||{};order={...order,fulfillment:snapshot,fulfillmentSnapshot:snapshot};}const next=normalize(order);sessionStorage.setItem(key,JSON.stringify([next,...list().filter(o=>o.id!==next.id)]));return next;}function total(order){return order.unitCents*order.quantity+(Number(order.aiCostCents)||0)+shipping(order);}function create(design,unitCents=50){const printer=null;const date=new Date(),stamp=String(date.getFullYear())+String(date.getMonth()+1).padStart(2,'0')+String(date.getDate()).padStart(2,'0'),id='PP'+stamp+crypto.randomUUID().replaceAll('-','').slice(0,8).toUpperCase();return update({id,designId:design.id,name:design.name,model:design.model,phoneColor:design.phoneColor||design.flowState?.phoneColor,cover:design.cover||design.image,source:design.source,aiUsed:design.source==='ai'||design.flowState?.editor?.source==='ai',aiCostCents:Number(design.aiCostCents)||0,unitCents,quantity:1,currency:'USD',status:'pending',createdAt:Date.now(),paymentMethod:null,printerId:printer?.id||null,fulfillment:printer?{method:'pickup',deviceId:printer.id}:{}});}function printed(id){const order=get(id);if(!order||order.status!=='paid')return order;const next=update({...order,status:'printed',printedAt:Date.now()});window.PopomoDesigns?.printed(order.designId,order.quantity);return next;}window.PopomoOrders={list,get,update,create,total,printed,shipping,deliveryShippingCents};})();
